 /* ===== VisionEase prototype – style.css ===== */
 :root{
   --primary:#165B9F; --primary-dark:#0D477F; --primary-mid:#2978B7;
   --tint:#C1E1F9; --bg:#F6FBFF; --accent:#83E2E9;
   --ink:#10283f; --muted:#4a6076; --line:#dbe8f3; --white:#fff;
   --danger:#a93226; --ok:#156b45; --warn:#8a5a0b;
   --radius:14px; --radius-sm:8px; --shadow:0 6px 24px rgba(13,71,127,.10);
   --container:1180px; --header-h:72px;
   --font:"Segoe UI","Be Vietnam Pro",Roboto,"Helvetica Neue",Arial,sans-serif;
 }
 *,*::before,*::after{box-sizing:border-box}
 html{scroll-behavior:smooth}
 body{margin:0;font-family:var(--font);color:var(--ink);background:var(--white);line-height:1.6;font-size:16px;-webkit-font-smoothing:antialiased}
 img{max-width:100%;display:block}
 a{color:var(--primary);text-decoration:none}
 a:hover{color:var(--primary-dark)}
 h1,h2,h3,h4{line-height:1.25;margin:0 0 .5em;color:var(--primary-dark);letter-spacing:-.01em}
 h1{font-size:clamp(1.9rem,4vw,2.9rem)} h2{font-size:clamp(1.5rem,3vw,2.05rem)} h3{font-size:1.15rem}
 p{margin:0 0 1em}
 ul{margin:0;padding:0;list-style:none}
 button,input,select,textarea{font:inherit;color:inherit}
 .container{width:min(var(--container),100% - 40px);margin-inline:auto}
 .section{padding:64px 0}
 .section--tint{background:var(--bg)}
 .section__head{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:28px;flex-wrap:wrap}
 .section__head p{color:var(--muted);margin:0;max-width:560px}
 .eyebrow{display:inline-block;font-size:.8rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--primary-mid);margin-bottom:8px}
 .sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
 :focus-visible{outline:3px solid var(--accent);outline-offset:2px}

 /* Buttons */
 .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:12px 22px;border-radius:999px;border:2px solid transparent;font-weight:600;cursor:pointer;background:var(--primary);color:#fff;transition:background .2s,transform .15s,box-shadow .2s;text-align:center}
 .btn:hover{background:var(--primary-dark);color:#fff;transform:translateY(-1px);box-shadow:0 6px 16px rgba(22,91,159,.25)}
 .btn--ghost{background:transparent;color:var(--primary);border-color:var(--primary)}
 .btn--ghost:hover{background:var(--primary);color:#fff}
 .btn--light{background:#fff;color:var(--primary)} .btn--light:hover{background:var(--tint);color:var(--primary-dark)}
 .btn--sm{padding:8px 16px;font-size:.9rem}
 .btn--block{width:100%}
 .btn[disabled]{opacity:.5;cursor:not-allowed;transform:none;box-shadow:none}
 .link-btn{background:none;border:0;color:var(--primary);cursor:pointer;padding:0;font-weight:600}
 .link-btn:hover{text-decoration:underline}

 /* Notice bar */
 .notice{background:var(--primary-dark);color:#dff0ff;font-size:.85rem;text-align:center;padding:6px 16px}

 /* Header */
 .site-header{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.96);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
 .header__inner{display:flex;align-items:center;gap:20px;min-height:var(--header-h)}
 .brand{flex:0 0 auto;display:inline-flex;align-items:center;line-height:0}
 .brand img{height:30px;width:190px;max-width:none;object-fit:contain;object-position:left center}
 .nav{display:flex;gap:4px;margin-left:12px}
 .nav a{white-space:nowrap;padding:8px 11px;border-radius:999px;color:var(--ink);font-weight:500;font-size:.95rem}
 .nav a:hover{background:var(--bg);color:var(--primary)}
 .nav a[aria-current="page"]{background:var(--tint);color:var(--primary-dark);font-weight:600}
 .header__tools{margin-left:auto;display:flex;align-items:center;gap:8px}
 .search-box{position:relative}
 .search-box input{width:220px;padding:9px 14px 9px 38px;border:1.5px solid var(--line);border-radius:999px;background:var(--bg);transition:border-color .2s,width .2s}
 .search-box input:focus{border-color:var(--primary);outline:none;width:260px;background:#fff;box-shadow:0 0 0 3px rgba(41,120,183,.15)}
 .search-box svg{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:16px;height:16px;color:var(--muted)}
 .suggest{position:absolute;top:calc(100% + 6px);left:0;right:0;background:#fff;border:1px solid var(--line);border-radius:var(--radius-sm);box-shadow:var(--shadow);overflow:hidden;display:none;min-width:260px}
 .suggest.open{display:block}
 .suggest a{display:flex;gap:10px;align-items:center;padding:8px 12px;color:var(--ink);font-size:.92rem}
 .suggest a:hover{background:var(--bg)}
 .suggest img{width:36px;height:36px;border-radius:6px}
 .icon-btn{position:relative;width:42px;height:42px;display:grid;place-items:center;border-radius:50%;border:0;background:transparent;cursor:pointer;color:var(--primary-dark)}
 .icon-btn:hover{background:var(--bg)}
 .icon-btn svg{width:22px;height:22px}
 .badge{position:absolute;top:2px;right:0;min-width:18px;height:18px;padding:0 5px;border-radius:9px;background:var(--primary);color:#fff;font-size:.7rem;display:grid;place-items:center;font-weight:700}
 .menu-toggle{display:none}

 /* Hero */
 .hero{background:radial-gradient(1200px 500px at 85% 10%,var(--tint),transparent 60%),linear-gradient(180deg,var(--bg),#fff);overflow:hidden}
 .hero__inner{display:grid;grid-template-columns:1.05fr .95fr;gap:40px;align-items:center;padding:56px 0 64px}
 .hero p.lead{font-size:1.1rem;color:var(--muted);max-width:520px}
 .hero__cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:22px}
 .hero__stats{display:flex;gap:28px;margin-top:30px;flex-wrap:wrap}
 .hero__stats strong{display:block;font-size:1.5rem;color:var(--primary-dark)}
 .hero__stats span{color:var(--muted);font-size:.9rem}
 .slider{position:relative;border-radius:24px;overflow:hidden;box-shadow:var(--shadow);background:var(--tint);aspect-ratio:1/1;max-width:520px;margin-left:auto;width:100%}
 .slide{position:absolute;inset:0;opacity:0;transition:opacity .6s;display:flex;flex-direction:column;justify-content:flex-end}
 .slide.active{opacity:1}
 .slide img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
 .slide__cap{position:relative;margin:16px;padding:12px 16px;background:rgba(255,255,255,.92);border-radius:var(--radius-sm);font-weight:600;color:var(--primary-dark);display:flex;justify-content:space-between;gap:12px;align-items:center}
 .slider__dots{position:absolute;top:14px;left:0;right:0;display:flex;justify-content:center;gap:6px;z-index:2}
 .slider__dots button{width:9px;height:9px;border-radius:50%;border:0;background:rgba(255,255,255,.7);cursor:pointer;padding:0}
 .slider__dots button.active{background:var(--primary);width:24px;border-radius:6px}

 /* Cards / grid */
 .grid{display:grid;gap:22px}
 .grid--4{grid-template-columns:repeat(4,1fr)} .grid--3{grid-template-columns:repeat(3,1fr)} .grid--2{grid-template-columns:repeat(2,1fr)}
 .card{background:#fff;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;transition:box-shadow .2s,transform .2s,border-color .2s}
 .card:hover{box-shadow:var(--shadow);transform:translateY(-3px);border-color:var(--tint)}
 .cat-card{padding:26px;display:flex;flex-direction:column;gap:8px;height:100%;background:linear-gradient(160deg,#fff,var(--bg))}
 .cat-card .ico{width:48px;height:48px;border-radius:12px;background:var(--tint);display:grid;place-items:center;color:var(--primary)}
 .cat-card .ico svg{width:26px;height:26px}
 .cat-card p{color:var(--muted);margin:0;flex:1}
 .product-card{display:flex;flex-direction:column;height:100%}
 .product-card__img{position:relative;aspect-ratio:1/1;background:var(--bg)}
 .product-card__img img{width:100%;height:100%;object-fit:contain;object-position:center;mix-blend-mode:multiply;padding:10px}
 .tag{position:absolute;top:10px;left:10px;background:var(--primary);color:#fff;font-size:.72rem;font-weight:700;padding:3px 9px;border-radius:999px}
 .tag--sale{background:var(--danger)}
 .product-card__body{padding:14px 16px 16px;display:flex;flex-direction:column;gap:6px;flex:1}
 .product-card__body h3{font-size:1rem;margin:0;min-height:2.5em;color:var(--ink)}
 .product-card__body h3 a{color:inherit}
 .meta{font-size:.84rem;color:var(--muted)}
 .price{font-weight:700;color:var(--primary-dark);font-size:1.08rem}
 .price del{font-weight:400;color:var(--muted);font-siz

