 .policy details{border:1px solid var(--line);border-radius:var(--radius-sm);padding:14px 18px;margin-bottom:10px;background:#fff}
 .policy summary{cursor:pointer;font-weight:700;color:var(--primary-dark)}
 .policy details[open]{background:var(--bg)}
 .banner-img{border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow)}

 /* Footer */
 .site-footer{background:var(--primary-dark);color:#cfe3f6;padding:48px 0 22px;margin-top:0}
 .footer__grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:28px}
 .site-footer h4{color:#fff;font-size:1rem}
 .site-footer a{color:#cfe3f6} .site-footer a:hover{color:#fff}
 .site-footer li{padding:3px 0}
 .footer__logo{background:#fff;border-radius:10px;padding:10px 14px;display:inline-block;margin-bottom:12px}
 .footer__logo img{height:34px;width:170px;object-fit:contain}
 .footer__bottom{border-top:1px solid rgba(255,255,255,.15);margin-top:28px;padding-top:16px;font-size:.84rem;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
 .news-form{display:flex;gap:8px;margin-top:8px}
 .news-form input{flex:1;min-width:0;padding:10px 14px;border-radius:999px;border:0}
 .news-note{font-size:.78rem;margin-top:6px;opacity:.85}

 /* Drawer / modal */
 .overlay{position:fixed;inset:0;background:rgba(9,32,56,.5);opacity:0;pointer-events:none;transition:opacity .25s;z-index:80}
 .overlay.open{opacity:1;pointer-events:auto}
 .drawer{position:fixed;top:0;right:0;height:100%;width:min(420px,100%);background:#fff;z-index:90;transform:translateX(100%);transition:transform .3s;display:flex;flex-direction:column;box-shadow:-10px 0 40px rgba(0,0,0,.15)}
 .drawer.open{transform:none}
 .drawer__head,.drawer__foot{padding:16px 20px;border-bottom:1px solid var(--line)}
 .drawer__foot{border-top:1px solid var(--line);border-bottom:0}
 .drawer__body{flex:1;overflow-y:auto;padding:8px 20px}
 .cart-item{display:grid;grid-template-columns:70px 1fr auto;gap:12px;padding:14px 0;border-bottom:1px solid var(--line);align-items:center}
 .cart-item img{width:70px;height:70px;border-radius:10px;background:var(--bg)}
 .cart-item h4{font-size:.95rem;margin:0 0 2px;color:var(--ink)}
 .row{display:flex;justify-content:space-between;gap:10px;padding:3px 0}
 .row--total{font-weight:800;font-size:1.1rem;color:var(--primary-dark);border-top:1px solid var(--line);margin-top:6px;padding-top:10px}
 .modal{position:fixed;inset:0;display:grid;place-items:center;z-index:100;padding:16px;visibility:hidden;opacity:0;background:rgba(13,43,74,0);transition:opacity .22s,visibility .22s,background .22s}
 .modal.open{visibility:visible;opacity:1;background:rgba(13,43,74,.5)}
 .modal__box{background:#fff;border-radius:18px;width:min(560px,100%);max-height:92vh;overflow-y:auto;padding:26px;box-shadow:0 20px 60px rgba(0,0,0,.25);position:relative}
 .modal__box--wide{width:min(760px,100%)}
 .modal__close{position:absolute;top:12px;right:12px}
 .radio-card{display:flex;gap:10px;align-items:flex-start;padding:12px 14px;border:1.5px solid var(--line);border-radius:var(--radius-sm);margin-bottom:8px;cursor:pointer}
 .radio-card:has(input:checked){border-color:var(--primary);background:var(--bg)}
 .radio-card input{margin-top:5px;accent-color:var(--primary)}
 .toast-wrap{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:200;display:flex;flex-direction:column;gap:8px;align-items:center}
 .toast{background:var(--primary-dark);color:#fff;padding:11px 20px;border-radius:999px;box-shadow:var(--shadow);font-size:.92rem;max-width:min(92vw,520px);animation:toastIn .28s ease-out both}
 .toast--err,.toast--error{background:var(--danger)}
 @keyframes toastIn{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
 @keyframes toastOut{to{opacity:0;transform:translateY(24px)}}

 /* Chat widget */
 .chat-fab{position:fixed;right:20px;bottom:20px;z-index:70;width:58px;height:58px;border-radius:50%;border:0;background:var(--primary);color:#fff;cursor:pointer;box-shadow:0 8px 24px rgba(22,91,159,.4);display:grid;place-items:center}
 .chat-fab:hover{background:var(--primary-dark)} .chat-fab svg{width:26px;height:26px}
 .chat{position:fixed;right:20px;bottom:90px;width:min(370px,calc(100% - 24px));height:min(520px,calc(100vh - 120px));background:#fff;border-radius:18px;box-shadow:0 16px 50px rgba(0,0,0,.25);z-index:75;display:none;flex-direction:column;overflow:hidden}
 .chat.open{display:flex}
 .chat__head{background:var(--primary);color:#fff;padding:14px 16px;display:flex;justify-content:space-between;align-items:center}
 .chat__head small{display:block;opacity:.85}
 .chat__body{flex:1;overflow-y:auto;padding:14px;background:var(--bg);display:flex;flex-direction:column;gap:10px}
 .msg{max-width:86%;padding:9px 13px;border-radius:14px;font-size:.93rem;line-height:1.5}
 .msg--bot{background:#fff;border:1px solid var(--line);align-self:flex-start;border-bottom-left-radius:4px}
 .msg--me{background:var(--primary);color:#fff;align-self:flex-end;border-bottom-right-radius:4px}
 .msg a{font-weight:600}
 .quick{display:flex;flex-wrap:wrap;gap:6px;padding:8px 12px;border-top:1px solid var(--line);background:#fff}
 .quick button{border:1px solid var(--line);background:var(--bg);border-radius:999px;padding:5px 11px;font-size:.8rem;cursor:pointer}
 .quick button:hover{border-color:var(--primary)}
 .chat__form{display:flex;gap:8px;padding:10px;border-top:1px solid var(--line);background:#fff}
 .chat__form input{flex:1;padding:10px 14px;border:1.5px solid var(--line);border-radius:999px}
 .chat__form input:focus{outline:none;border-color:var(--primary)}

 /* Responsive */
 @media (max-width:1024px){
   .grid--4{grid-template-columns:repeat(3,1fr)}
   .footer__grid{grid-template-columns:1fr 1fr}
