 function botReply(text) {
   const q = norm(text);
   const health = /(dau|nhuc|do mat|mat do|bi do|ngua|mo mat|nhin mo|kho mat|chay nuoc|sung|thuoc|benh|chan doan|tre em|thanh phan|di ung)/.test(q);
